import nanosurf

# Initialize AFM
spm = nanosurf.SPM()
application = spm.application
scan = application.Scan

# Check for ScanConfig or similar
print("Looking for configuration objects...")
for attr in dir(scan):
    if not attr.startswith('_'):
        try:
            obj = getattr(scan, attr)
            obj_type = type(obj).__name__
            if 'Config' in attr or 'Parameter' in attr or 'Setting' in attr:
                print(f"  {attr}: {obj_type}")
        except:
            pass

# Try accessing through application
print("\nChecking application level...")
for attr in dir(application):
    if not attr.startswith('_') and ('Config' in attr or 'Parameter' in attr):
        print(f"  {attr}")

# Clean up
del spm
